const rtdal007222Source0004 = `na.locf.STFDF = function (object, na.rm = FALSE, ...) {
	nv = dim(object)[3]
	df = vector("list", nv)
	names(df) = names(object@data)
	for (i in 1:nv) {
		x = na.locf(as(object[,,i], "xts"), na.rm = na.rm, ...)
		df[[i]] = as.vector(t(x))
	}
	STFDF(object@sp, index(x), data.frame(df))
}`

