const rtdal007224Source0001 = `plot.STF = function(x, y, ...) {
	ny = length(x@sp)
	yy = 1:ny
	xx = index(x@time)
	nx = length(xx)
	time = rep(xx, each = ny)
	space = rep(yy, nx)
	plot(time, space, ...)
}`

const rtdal007224Source0003 = `plot.STFDF = function(x, y, ..., col = ifelse(all.na, "red", "black")) {
	all.na = apply(x@data, 1, function(x) all(is.na(x)))
	plot(geometry(x), col = col, ...)
}`

const rtdal007224Source0005 = `plot.STS = function(x, y, ...) {
	yy = 1:length(x@sp)
	xx = index(x@time)
	time = xx[x@index[,2]]
	space = yy[x@index[,1]]
	plot(time, space, ...)
}`

const rtdal007224Source0007 = `plot.STSDF = function(x, y, ..., col = ifelse(any.na, "red", "black")) {
	any.na = apply(x@data, 1, function(x) any(is.na(x)))
	plot(geometry(x), col = col, ...)
}`

const rtdal007224Source0009 = `plot.STI = function(x, y, ...) {
	space = 1:length(x@sp)
	time = index(x@time)
	plot(x = time, y = space, ...)
}`

const rtdal007224Source0011 = `plot.STT = function(x, y, ..., type = 'l', col = 1:length(x@traj), 
		labels = FALSE) {
	nt = sapply(x@traj, function(x) dim(x)[1])
	yy0 = 1:sum(nt)
	grp = rep(1:length(nt), times = nt)
	space = do.call(c, lapply(split(yy0, grp), function(x) c(x, NA)))
	time = do.call(c, lapply(x@traj, function(x) c(index(x), NA)))
	plot(x = time, y = space, ..., type = type, col = col)
	# labels(x2, y2, pos=4, sapply(x@traj, function(x) attr(x, "burst)))
}`

