const rtdal007253Source0010 = `cov.mat <- function(h, theta,  ..., eps=getOption("spam.eps")) {

  theta <- .par.check.cov(theta, 3)
  if (theta[1] < eps) return( cov.nug(h, theta[2] + theta[3]))
  # range so small, is considered as nugget
  if (is.spam(h)) {
    tmp <- h@entries/theta[1]
    ypos <- tmp < eps
    npos <- !ypos

    if (any(ypos)) {
      h@entries[ypos] <- theta[2] + theta[4] }
    if (any(npos)) {
      h@entries[npos] <- theta[2] * (((2^(-(theta[3] - 1)))/gamma(theta[3])) *
                                       (tmp[npos]^theta[3]) *
                                       besselK(tmp[npos], nu=theta[3])) }
  } else {
    tmp <- c(h)/theta[1]
    ypos <- tmp < eps
    npos <- !ypos

    if (any(ypos)) {
      h[ypos] <- theta[2] + theta[4] }
    if (any(npos)) {
      h[npos] <- theta[2] * (((2^(-(theta[3] - 1)))/gamma(theta[3])) *
                               (tmp[npos]^theta[3]) *
                               besselK(tmp[npos], nu=theta[3])) }
  }

  return(h)
}`

const rtdal007253Source0011 = `cov.finnmat <- function (h, theta, ..., eps = getOption("spam.eps"))
{
  theta <- .par.check.cov(theta, 3)
  if (theta[1] < eps) return( cov.nug(h, theta[2] + theta[3]))
  if (is.spam(h)) {
    tmp <- sqrt(8 * theta[3])/theta[1] * h@entries
    ypos <- tmp < eps
    npos <- !ypos

    if (any(ypos)) {
      h@entries[ypos] <- theta[2] + theta[4]
    }
    if (any(npos)) {
      h@entries[npos] <- theta[2] * (((2^(-(theta[3] - 1)))/gamma(theta[3])) *
                                       (tmp[npos]^theta[3]) *
                                       besselK(tmp[npos], nu = theta[3]))
    }
  } else {
    tmp <- sqrt(8 * theta[3])/theta[1] * c(h)
    ypos <- tmp < eps
    npos <- !ypos
    if (any(ypos)) {
      h[ypos] <- theta[2] + theta[4]
    }
    if (any(npos)) {
      h[npos] <- theta[2] * (((2^(-(theta[3] - 1)))/gamma(theta[3])) *
                               (tmp[npos]^theta[3]) *
                               besselK(tmp[npos], nu = theta[3])) }
  }

  return(h)
}`

const rtdal007253Source0012 = `cov.exp <- function(h, theta, ..., eps=getOption("spam.eps")) {

  theta <- .par.check.cov(theta,2)
  if (theta[1] < eps) return( cov.nug(h, theta[2] + theta[3]))
  # range so small, is considered as nugget
  if (is.spam(h)) {
    tmp <- h@entries/theta[1]
    ypos <- tmp < eps
    npos <- !ypos

    if (any(ypos)) {
      h@entries[ypos] <- theta[2] + theta[3] }
    if (any(npos)) {
      h@entries[npos] <- theta[2] * exp( -tmp[npos]) }

  } else {
    tmp <- c(h)/theta[1]
    ypos <- tmp < eps
    npos <- !ypos

    if (any(ypos)) {
      h[ypos] <- theta[2] + theta[3] }
    if (any(npos)) {
      h[npos] <- theta[2] * exp( -tmp[npos])   }
  }

  return(h)
}`

