const rtdal007254Source0074 = `.spam.diagmulmat <- function(x,y){
    nrow <- y@dimension[1]
    if(length(x) != nrow)
        stop("not conformable for multiplication")

    SS <- .format.spam(y)

    z <- .C64("diagmua",
              SIGNATURE = c(SS$signature,
                  "double", SS$signature, "double"),

              nrow,

              entries = y@entries,
              y@rowpointers,
              as.vector(x,"double"),

              INTENT = c("r",
                  "rw", "r", "r"),
              NAOK=getOption("spam.NAOK"),
              PACKAGE = SS$package)$entries

    y@entries <- z
    return(y)
}`

