const rtdal007276Source0001 = `rowSums.spam <- function(x,...) {
    ## print("1")
    if(  getOption("spam.force64") )
        SS <- .format64()
    else
        SS <- .format.spam(x)
    
    return(.C64("rowsums",
                SIGNATURE=c("double", SS$signature, SS$signature,
                    "double"),

                x@entries,
                x@rowpointers,
                x@dimension[1],

                rs = vector_dc("double", x@dimension[1]),

                INTENT=c("r", "r", "r",
                    "w"),
                NAOK = getOption("spam.NAOK"),
                PACKAGE = SS$package)$rs )
}`

