const rtdal007331Source0036 = `"slm.wfit" <-
function (x, y, weights,  ...)
{
    if (!is.matrix.csr(x))
        stop("model matrix must be in sparse csr mode")
    if (!is.numeric(y))
        stop("response must be numeric")
    if (any(weights < 0))
        stop("negative weights not allowed")
    w <- sqrt(weights)
    x <- as(w,"matrix.diag.csr") %*% x
    y <- y * w
    fit <- slm.fit.csr(x, y,  ...)
    fit$contrasts <- attr(x, "contrasts")
    fit
}`

const rtdal007331Source0037 = `"slm.fit.csr" <-
function (x, y, ...)
{
#    n <- length(y)
    if(is.matrix(y))
	n <- dim(y)[1]
    else
        n <- length(y)
    p <- x@dimension[2]
    if (n != x@dimension[1])
        stop("x and y don't match n")
    chol <- chol(t(x)%*%x, ...)
    xy <- t(x) %*% y
    coef <- backsolve(chol,xy)
    fitted <-  as.matrix(x %*% coef)
    resid <- y - fitted
    df <- n - p
    list(coefficients=coef, chol=chol, residuals=resid,
         fitted=fitted, df.residual = df)
}`

