const rtdal007331Source0089 = `setMethod("as.matrix", "matrix.csr", function(x){
	nrow <- x@dimension[1]
        ncol <- x@dimension[2]
        if(length(xa <- x@ra) == 1L && is.na(xa)){ # trap zero matrix
                dns <- matrix(0,nrow=nrow,ncol=ncol)
                return(dns)
                }
        nan <- is.nan(xa)
        infty <-  is.infinite(xa) & xa > 0
        ninfty <- is.infinite(xa) & xa < 0
        uniq <- rnorm(3)
        while(any(uniq %in% xa[!(nan|infty|ninfty)]))
                uniq <- rnorm(3)
        x@ra[ nan  ] <- uniq[1]
        x@ra[ infty] <- uniq[2]
        x@ra[ninfty] <- uniq[3]
        z <- .Fortran(f_csrdns,
                as.integer(nrow),
                as.integer(ncol),
                as.double(x@ra),
                as.integer(x@ja),
                as.integer(x@ia),
                dns = double(nrow*ncol),
                ndns = as.integer(nrow),
                ierr = integer(1))[c("ierr", "dns")]
        if(z$ierr != 0) stop("insufficient space for dns")
        dns <- matrix(z$dns,nrow=nrow,ncol=ncol)
        dns[dns==uniq[1]] <- NaN
        dns[dns==uniq[2]] <- Inf
        dns[dns==uniq[3]] <- -Inf
        return(dns)
	})`

const rtdal007331Source0102 = "setMethod(\"diff\",\"matrix.csr\", function(x, lag = 1, differences = 1, ...) {\n    xlen <- dim(x)[1]\n    if (length(lag) > 1 || length(differences) > 1 || lag < 1 ||\n        differences < 1)\n        stop(\"`lag' and `differences' must be integers >= 1\")\n    if (lag * differences >= xlen)\n        stop(\"lag * differences >= nrow\")\n     r <- x\n    i1 <- -1:-lag\n    for (i in 1:differences) r <- r[i1,] - r[-nrow(r):-(nrow(r) - lag + 1),]\n    r\n})"

const rtdal007331Source0107 = `setMethod("diag", "matrix.csr", function (x, nrow, ncol, names = TRUE) {
    if (is.matrix.csr(x) && missing(nrow) && missing(ncol)) {
        if ((m <- min(d <- dim(x))) == 0)
            return(numeric(0))
        y <- rep(0,m)
        ia <- rep(1:d[1], diff(x@ia))
        id <- which(ia == x@ja)
        y[x@ja[id]] <- x@ra[id]
        ## n <- sum(ia == x@ja)
        if(names && is.list(nms <- dimnames(x)) && !any(sapply(nms, is.null)) &&
           all((nm <- nms[[1]][1:m]) == nms[[2]][1:m]))
            names(y) <- nm
        y
    }
    else stop("diag method for class matrix.csr doesn't understand nrow and ncol args")
})`

