const rtdal007367Source0001 = `auc <- function(X, ...) { UseMethod("auc") }`

const rtdal007367Source0002 = `needROC <- function(...) {
  ## these arguments require the use of roc()
  any(c("observations", "baseline", "weights") %in% names(list(...)))
}`

const rtdal007367Source0003 = `auc.ppp <- function(X, covariate, ...,
                    high=TRUE,  subset=NULL) {
  verifyclass(X, "ppp")
  if(needROC(...)) {
    ro <- roc(X, covariate, ..., high=high, subset=subset)
    result <- auc(ro)
  } else {
    nullmodel <- exactppm(X)
    result <- aucData(covariate, nullmodel, ..., high=high, subset=subset)
  }
  return(result)
}`

const rtdal007367Source0004 = `aucData <- function(covariate, nullmodel, ..., high=TRUE,
                    interpolate=FALSE, jitter=FALSE, subset=NULL,
                    covariateAtPoints=discrimAtPoints,
                    discrimAtPoints=NULL) {
  d <- spatialCDFframe(nullmodel, covariate, ...,
                       covariateAtPoints=covariateAtPoints,
                       interpolate=interpolate, jitter=jitter,
                       subset=subset)
  U <- d$values$U
  EU <- mean(U)
  result <- if(high) EU else (1 - EU)
  return(result)
}`

const rtdal007367Source0005 = `auc.im <- function(X, covariate, ..., high=TRUE) {
  ro <- roc(X, covariate, ..., high=high)
  auc(ro)
}`

const rtdal007367Source0006 = `auc.roc <- function(X, ...) {
  with(X, colMeans(.))
}`

const rtdal007367Source0007 = `auc.spatialCDFframe <- function(X, ..., high=TRUE) {
  trap.extra.arguments(...)
  U <- X$values$U
  EU <- mean(U)
  result <- if (high) EU else (1 - EU)
  return(result)
}`

