const rtdal007384Source0001 = `bw.stoyan <- function(X, co = 0.15, extrapolate=FALSE, ...) 
{
  stopifnot(is.ppp(X))
  n <- max(1, npoints(X))
  W <- Window(X)
  a <- area(W)
  ## Stoyan rule for halfwidth of Epanechnikov kernel
  ## Stoyan & Stoyan 1995, eq (15.16), page 285
  hepa <- co/sqrt(n/a)
  ## convert to bandwidth (standard deviation)
  bw <- hepa/sqrt(5)
  ## extrapolate? (Baddeley Davies and Hazelton 2025)
  if(extrapolate)
    bw <- bw * ((100/n)^(1/5))
  return(bw)
}`

const rtdal007384Source0002 = `bw.fiksel <- function(X, co = 0.1, extrapolate=FALSE, ...) 
{
  stopifnot(is.ppp(X))
  n <- max(1, npoints(X))
  W <- Window(X)
  a <- area(W)
  ## Fiksel rule for bandwidth (standard deviation) of Epanechnikov kernel
  bw <- co/sqrt(n/a)
  ## extrapolate? (Baddeley Davies and Hazelton 2025)
  if(extrapolate)
    bw <- bw * ((100/n)^(1/5))
  return(bw)
}`

