const rtdal007387Source0002 = `clarkevans.test <- function(X, ..., 
                            correction,
                            clipregion=NULL,
                            alternative=c("two.sided", "less", "greater",
                                          "clustered", "regular"),
                            method = c("asymptotic", "MonteCarlo"),
                            nsim=999
                            ) {
  Xname <- short.deparse(substitute(X))
  miss.nsim <- missing(nsim)
  method <- match.arg(method)
  
  verifyclass(X, "ppp")
  W <- Window(X)
  nX <- npoints(X)

  if(missing(correction) || is.null(correction)) {
    correction <- switch(method,
                         MonteCarlo = "none",
                         asymptotic = if(is.rectangle(W)) "Donnelly" else "cdf")
  } else {
    #' validate SINGLE correction
    correction <- pickoption("correction", correction,
                             c(none="none",
                               Donnelly="Donnelly",
                               donnelly="Donnelly",
                               guard="guard",
                               cdf="cdf"))
  }
  
  switch(correction,
         none={
           corrblurb <- "No edge correction"
         },
         Donnelly={
           if(W$type != "rectangle")
             stop("Donnelly correction only available for rectangular windows")
           corrblurb <- "Donnelly correction"
         },
         guard={
           if(is.null(clipregion))
             stop("clipregion not specified")
           clipregion <- as.owin(clipregion)
           corrblurb <- "Guard correction"
         },
         cdf={
           corrblurb <- "CDF correction"
         })

  # alternative hypothesis
  if(missing(alternative) || is.null(alternative))
    alternative <- "two.sided"
  alternative <- pickoption("alternative", alternative,
                           c(two.sided="two.sided",
                             less="less",
                             clustered="less",
                             greater="greater",
                             regular="greater"))

  altblurb <-
    switch(alternative,
           two.sided="two-sided",
           less="clustered (R < 1)",
           greater="regular (R > 1)")

  # compute observed value
  statistic <- clarkevansCalc(X, correction=correction, clipregion=clipregion,
                              working=TRUE)
  working <- attr(statistic, "working")
  #
  switch(method,
         asymptotic = {
           #' use asymptotic standard Normal reference
           #' get appropriate standard error
           SE.R <- switch(correction,
                          none     = working[["SEnaive"]],
                          guard    = working[["SEguard"]],
                          Donnelly = working[["SEkevin"]],
                          cdf      = working[["SEcdf"]])
           #' standardised test statistic
           Z <- as.numeric((statistic - 1)/SE.R)
           p.value <- switch(alternative,
                             less=pnorm(Z),
                             greater=1 - pnorm(Z),
                             two.sided= 2*(1-pnorm(abs(Z))))
           pvblurb <- "Z-test"
         },
         MonteCarlo = {
           #' Monte Carlo p-value
           sims <- numeric(nsim)
           for(i in seq_len(nsim)) {
             Xsim <- runifpoint(nX, win=W)
             sims[i] <- clarkevansCalc(Xsim, correction=correction,
                                       clipregion=clipregion)
           }
           p.upper <- (1 + sum(sims >= statistic))/(1.0 + nsim)
           p.lower <- (1 + sum(sims <= statistic))/(1.0 + nsim)
           p.value <- switch(alternative,
                             less=p.lower,
                             greater=p.upper,
                             two.sided=min(1, 2*min(p.lower, p.upper)))
           pvblurb <- paste("Monte Carlo test based on",
                            nsim, "simulations of CSR with fixed n")
         })

  statistic <- as.numeric(statistic)
  names(statistic) <- "R"
  
  out <- list(statistic=statistic,
              p.value=p.value,
              alternative=altblurb,
              method=c("Clark-Evans test", corrblurb, pvblurb),
              data.name=Xname)
  class(out) <- "htest"
  return(out)
}`

const rtdal007387Source0003 = "clarkevansCalc <- function(X, correction=\"none\", clipregion=NULL,\n                           working=FALSE) {\n  # calculations for Clark-Evans index or test\n  W <- Window(X)\n  areaW <- area(W)\n  npts <- npoints(X)\n  intensity <- npts/areaW\n  # R undefined for empty point pattern\n  if(npts == 0)\n    return(NA)\n  # Dobs = observed mean nearest neighbour distance\n  nndistX <- nndist(X)\n  Dobs <- mean(nndistX)\n  # Dpois = Expected mean nearest neighbour distance for Poisson process\n  Dpois <- 1/(2*sqrt(intensity))\n\n  ## initialise\n  statistic <- NULL\n  SE.Dobs <- NULL\n  if(working) {\n    work <- list(areaW=areaW, npts=npts, intensity=intensity,\n                 Dobs=Dobs, Dpois=Dpois)\n    #' null standard error of Dobs = mean(nndist(X)) \n    SE.Dobs <- sqrt(((4-pi)*areaW)/(4 * pi))/npts  # sic\n  }\n\n  ## start computing results\n  \n  # Naive uncorrected value\n  if(\"none\" %in% correction) {\n    Rnaive <- Dobs/Dpois\n    statistic <- c(statistic, naive=Rnaive)\n    if(working) {\n      #' null standard error of Clark-Evans statistic Rnaive\n      SE.Rnaive <- SE.Dobs / Dpois\n      work <- append(work, list(SEnaive=SE.Rnaive))\n    }\n  }\n  #' Donnelly edge correction\n  if(\"Donnelly\" %in% correction) {\n     #' Edge corrected mean nearest neighbour distance, Donnelly 1978\n    if(W$type == \"rectangle\") {\n      perim <- perimeter(W)\n      Dkevin  <- Dpois + (0.0514+0.0412/sqrt(npts))*perim/npts\n      Rkevin <- Dobs/Dkevin\n      if(working) {\n        #' null standard error of adjusted Clark-Evans statistic Rkevin\n        SE.Rkevin <- SE.Dobs / Dkevin\n        work <- append(work,\n                       list(perim=perim,\n                            Dkevin=Dkevin,\n                            SEkevin=SE.Rkevin))\n      }\n    } else {\n      Rkevin <- NA\n    }\n    statistic <- c(statistic, Donnelly=Rkevin)\n  }\n  # guard area method\n  if(\"guard\" %in% correction && !is.null(clipregion)) {\n    #' use nn distances from points inside `clipregion'\n    ok <- inside.owin(X, , clipregion)\n    Dguard <- mean(nndistX[ok])\n    Rguard <- Dguard/Dpois\n    statistic <- c(statistic, guard=Rguard)\n    ## additional info\n    if(working) {\n      npts.guard <- sum(ok)\n      areaWclip <- area(clipregion)\n      #' null standard error of Dguard = mean(nndist(X[clipregion])) \n      SE.Dguard <- sqrt((4-pi)/(4 * pi * npts.guard * intensity))\n      #' null standard error of adjusted Clark-Evans statistic Rguard\n      SE.Rguard <- SE.Dguard / Dpois\n      work <- append(work,\n                     list(Dguard=Dguard,\n                          npts.guard=npts.guard,\n                          SEguard=SE.Rguard))\n\n    }\n  }\n  if(\"cdf\" %in% correction) {\n    # compute mean of estimated nearest-neighbour distance distribution G\n    G <- Gest(X)\n    numer <- stieltjes(function(x){x}, G)$km\n    denom <- stieltjes(function(x){rep.int(1, length(x))}, G)$km\n    Dcdf <- numer/denom\n    Rcdf <- Dcdf/Dpois\n    statistic <- c(statistic, cdf=Rcdf)\n    if(working) {\n      #' approximate null standard error of Dobs = mean(Gest(X)) \n      SE.Dcdf <- SE.Dobs\n      #' null standard error of Clark-Evans statistic Rcdf\n      SE.Rcdf <- SE.Dcdf/Dpois\n      work <- append(work, list(Dcdf=Dcdf,\n                                SEcdf=SE.Rcdf))\n    }\n  }\n\n  if(working) attr(statistic, \"working\") <- work\n\n  return(statistic)\n}"

